def esc(v): return html.escape(str(v),quote=True)
def bi(ar,en,tag='span',cls=''):
    return f'<{tag} class="{esc(cls)}" data-ar="{esc(ar)}" data-en="{esc(en)}">{esc(ar)}</{tag}>'
def value(v): return v if isinstance(v,str) else v['ar']
def bilingual(v,tag='span',cls=''): return bi(v['ar'],v['en'],tag,cls) if isinstance(v,dict) else f'<{tag} class="{cls}">{esc(v)}</{tag}>'
def ext(url,label,cls=''):return f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{label}</a>'
def tags(items):return '<div class="tags">'+''.join(f'<span>{esc(t)}</span>' for t in items)+'</div>'
def head(title_ar,title_en,desc,prefix='',canonical=BASE+'/',image=BASE+'/assets/portrait.jpeg',schema=None):
    data=json.dumps(schema or {'@context':'https://schema.org','@type':'Person','name':'Karim El-Gezawy','url':BASE,'image':BASE+'/assets/portrait.jpeg','jobTitle':'Senior Oracle APEX Developer & Instructor','sameAs':[s[1] for s in SOCIAL]},ensure_ascii=False).replace('</','<\\/')
    return f'''<!doctype html><html lang="ar" dir="rtl" data-theme="dark" data-title-ar="{esc(title_ar)}" data-title-en="{esc(title_en)}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title_ar)}</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#0c1518"><meta property="og:type" content="{'article' if schema and schema.get('@type') == 'Article' else 'website'}"><meta property="og:title" content="{esc(title_ar)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:image" content="{esc(image)}"><meta property="og:url" content="{esc(canonical)}"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{esc(canonical)}"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/site.css"><script defer src="{prefix}assets/site.js"></script><script type="application/ld+json">{data}</script></head><body>'''
def header(prefix=''):
    home=prefix+'index.html'
    nav=[('المشروعات','Projects','projects'),('الخبرة','Experience','experience'),('الشهادة','Certification','certification'),('المقالات','Articles','articles'),('تواصل','Contact','contact')]
    return f'''<a class="skip" href="#main">{bi('انتقل للمحتوى','Skip to content')}</a><header class="site-header"><div class="container header-inner"><a class="brand" href="{home}" aria-label="Karim El-Gezawy"><span class="brand-mark" aria-hidden="true">KE</span><span>{bi('كريم الجيزاوي','Karim El-Gezawy')}<small>ORACLE APEX DEVELOPER</small></span></a><nav class="site-nav" aria-label="Main navigation">{''.join(f'<a href="{home}#{anchor}">{bi(ar,en)}</a>' for ar,en,anchor in nav)}</nav><div class="header-actions"><button id="language-toggle" class="lang-btn" type="button" aria-label="Switch to English">English</button><button id="theme-toggle" class="icon-btn" type="button" aria-label="تبديل المظهر / Toggle theme" aria-pressed="false">☀</button></div></div></header>'''
def footer(prefix=''):
    return f'''<footer class="site-footer"><div class="container footer-inner"><p>© 2026 {bi('كريم الجيزاوي. معرفة تُشارك، وحلول تُبنى.','Karim El-Gezawy. Knowledge shared. Solutions built.')}</p><p>{bi('موقع مستقل مستضاف على GitHub Pages','Independent portfolio · GitHub Pages')} · <a class="back-top" href="#main">{bi('للأعلى ↑','Back to top ↑')}</a></p></div></footer></body></html>'''
def section_head(n,eyear,eyeen,ar,en,desc_ar='',desc_en='',action=''):
    return f'<div class="section-head"><div>{bi(n+" / "+eyear,n+" / "+eyeen,"span","eyebrow")}{bi(ar,en,"h2")}{bi(desc_ar,desc_en,"p") if desc_ar else ""}</div>{action}</div>'
def project_art(p):
    labels={'clinic':['YUNNI','Clinic','Finance','HR'],'service':['TRUELASE','Appointment','Service','Invoice'],'family':['FAMILY TREE','Parent','Family','Story'],'portal':['EMPLOYEE PORTAL','Request','Review','Decision'],'form':['HR FORMS','Capture','Validate','Submit'],'workflow':['APPROVAL FLOW','Request','Review','Approve'],'report':['BUSINESS REPORTS','Data','Report','Export'],'access':['ACCESS CONTROL','Role','Access','Action']}
    label,*parts=labels[p['visual']]
    return f'<div class="project-art visual-{p["visual"]}" aria-hidden="true"><div class="mini-window"><div class="window-top"><span>{label}</span><span class="window-dot"><i></i><i></i><i></i></span></div><div class="mini-row">'+''.join(f'<span>{x}</span>' for x in parts)+'</div></div></div>'
def project_card(p):
    fields=[('audience','لمن صُمم؟','Who it serves'),('challenge','التحدي','The challenge'),('role','دوري','My contribution'),('solution','الحل والوظائف','Solution & capabilities'),('outcome','القيمة العملية','Practical value')]
    dl=''.join(f'<div>{bi(ar,en,"dt")}{bilingual(p[key],"dd")}</div>' for key,ar,en in fields)
    search=value(p['name'])+' '+p['summary']['ar']+' '+p['summary']['en']
    return f'<article class="project" data-category="{p["category"]}" id="project-{p["id"]}">{project_art(p)}<div class="project-main">{bilingual(p["label"],"span","project-kicker")}{bilingual(p["name"],"h3")}{bilingual(p["summary"],"p","project-summary")}{tags(p["tags"])}<details><summary>{bi("اقرأ دراسة الحالة","Explore the case study")}</summary><dl class="case-details">{dl}</dl></details></div></article>'
