def article_directory():
    p='../';s=head('المقالات | كريم الجيزاوي','Articles | Karim El-Gezawy','مكتبة مقالات كريم الجيزاوي في Oracle APEX والبيانات وتطوير تطبيقات الأعمال.',p,BASE+'/articles/')+header(p)
