def article_pages():
    for a in ARTICLES:
        p='../../';target=OUT/'articles'/a['slug'];target.mkdir(parents=True,exist_ok=True)
        en=(CONTENT/'articles'/f'{a["slug"]}.en.md').read_text(encoding='utf-8');ar=(CONTENT/'articles'/f'{a["slug"]}.ar.md').read_text(encoding='utf-8')
        render=lambda text:markdown2.markdown(text,safe_mode='escape',extras=['fenced-code-blocks','tables','strike'])
        schema={'@context':'https://schema.org','@type':'Article','headline':a['title'],'author':{'@type':'Person','name':'Karim El-Gezawy','url':BASE},'inLanguage':['en','ar'],'mainEntityOfPage':a['canonical'],'image':BASE+'/'+a['cover']}
        s=head(a['titleAr']+' | كريم الجيزاوي',a['title']+' | Karim El-Gezawy',a['excerpt'],p,a['canonical'],BASE+'/'+a['cover'],schema)+header(p)
        s+='<main id="main" class="container"><div class="article-header"><a class="breadcrumb" href="../">'+bi('المكتبة التقنية ←','← Technical articles')+'</a>'+bi(a['titleAr'],a['title'],'h1')+'<div class="article-meta"><span>'+bi('بقلم كريم الجيزاوي','By Karim El-Gezawy')+'</span><span>EN / العربية</span><span>'+bi(str(a['minutes'])+' دقائق قراءة',str(a['minutes'])+' min read')+'</span></div></div><img class="article-cover" src="'+p+a['cover']+'" alt="" width="1200" height="630"><div class="article-layout"><nav class="article-toolbar" aria-label="Article versions"><a href="#english" lang="en">English version</a><a href="#arabic" lang="ar">النسخة العربية</a>'+ext(a['canonical'],bi('المصدر على Hashnode ↗','Original on Hashnode ↗'))+'</nav><section id="english" class="article-body" lang="en" dir="ltr"><h2 class="article-language-heading">English version</h2>'+render(en)+'</section><section id="arabic" class="article-body" lang="ar" dir="rtl"><h2 class="article-language-heading">النسخة العربية</h2>'+render(ar)+'</section><aside class="article-source">'+bi('نُشر هذا المقال أيضًا على Hashnode.','This article is also published on Hashnode.','p')+ext(a['canonical'],esc(a['title']))+'<p>'+ext(a['source'],bi('رابط المصدر أو البوست الأصلي','Source / original post'))+'</p>'+bi('صورة الغلاف مولدة بالذكاء الاصطناعي.' if a['aiCover'] else 'رسم توضيحي للموضوع.','Cover illustration generated with AI.' if a['aiCover'] else 'Topic illustration.','p')+'</aside></div></main>'+footer(p)
        (target/'index.html').write_text(s,encoding='utf-8')
def main():
    OUT.mkdir(exist_ok=True);home();article_directory();article_pages()
    (OUT/'.nojekyll').touch()
    urls=[BASE+'/',BASE+'/articles/']+[BASE+'/articles/'+a['slug']+'/' for a in ARTICLES]
    (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+esc(u)+'</loc></url>' for u in urls)+'</urlset>',encoding='utf-8')
    (OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n',encoding='utf-8')
    print(f'Built portfolio, article library, and {len(ARTICLES)} bilingual article pages in {OUT}')
if __name__=='__main__':main()
